class Solution {
    func findKthLargest(_ nums: [Int], _ k: Int) -> Int {
        var nums = nums
        let k = nums.count - k

        func quickSelect(_ l: Int, _ r: Int) -> Int {
            let pivot = nums[r]
            var p = l

            for i in l..<r {
                if nums[i] <= pivot {
                    nums.swapAt(i, p)
                    p += 1
                }
            }
            nums.swapAt(p, r)

            if p > k {
                return quickSelect(l, p - 1)
            } else if p < k {
                return quickSelect(p + 1, r)
            } else {
                return nums[p]
            }
        }

        return quickSelect(0, nums.count - 1)
    }
}
